async function memberAction(id:string,action:string,extra:any={}){try{const r=await fetch('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action,...extra})});const d:any=await r.json();if(!r.ok)throw Error(d.error);toast.success(({approve:'Access approved',reject:'Registration rejected',remove:'Access removed',update:'Role and team updated'} as any)[action]);loadMembers();}catch(e:any){toast.error(e.message);}}
